const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, HeadingLevel,
  LevelFormat, VerticalAlign
} = require('docx');
const fs = require('fs');

const border = { style: BorderStyle.SINGLE, size: 1, color: "AAAAAA" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

const headerBlue = "1B3A5C";
const lightBlue = "D6E4F0";
const altRow = "F0F4F8";
const white = "FFFFFF";

function headerCell(text, width) {
  return new TableCell({
    borders,
    width: { size: width, type: WidthType.DXA },
    shading: { fill: headerBlue, type: ShadingType.CLEAR },
    margins: { top: 100, bottom: 100, left: 120, right: 120 },
    children: [new Paragraph({
      alignment: AlignmentType.LEFT,
      children: [new TextRun({ text, bold: true, color: "FFFFFF", size: 20, font: "Arial" })]
    })]
  });
}

function dataCell(text, width, fill, bold = false, italic = false) {
  return new TableCell({
    borders,
    width: { size: width, type: WidthType.DXA },
    shading: { fill, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({
      children: [new TextRun({ text, bold, italic, size: 19, font: "Arial" })]
    })]
  });
}

const timeline = [
  {
    date: "10/08/2024",
    provider: "VUMC Primary Care, Brentwood",
    event: "Annual physical — 5 days before assault",
    detail: "Musculoskeletal exam noted as normal; full cervical range of motion documented. No neck complaints recorded. Establishes baseline of no pre-existing neck injury at time of visit.",
    category: "Baseline"
  },
  {
    date: "10/13/2024",
    provider: "N/A — Incident Date",
    event: "ASSAULT: Strangulation by ex-husband",
    detail: "Documented in subsequent VUMC clinical notes as an \"altercation on 10/13/2024.\" Referenced in Vanderbilt Orthopaedics records (Dr. Schneider, 5/19/2025) as the precipitating event for neck injury. Initial onset of neck strain.",
    category: "Incident"
  },
  {
    date: "Feb 2025",
    provider: "Outside/Chiropractic",
    event: "Onset of acute radicular symptoms during weightlifting",
    detail: "Sudden numbness in left arm during a row exercise. Chiropractor x-ray reveals slightly compressed disc in neck. Began approximately 10 sessions of decompression therapy, laser treatment, and adjustments. Referenced in VUMC records (5/19/2025 visit).",
    category: "Worsening"
  },
  {
    date: "05/19/2025",
    provider: "VUMC Primary Care, Brentwood (Schapker, APRN)",
    event: "First VUMC neck complaint visit — Cervicalgia + left arm numbness",
    detail: "Chief complaint: left neck/shoulder pain with tingling and numbness down left arm. X-ray finding documented: \"slightly compressed disc in the neck.\" Diagnosis: Cervicalgia with associated left arm numbness. Prescriptions: Prednisone 40mg x5 days; Tizanidine (muscle relaxer) as needed. Referral placed to Orthopaedics.",
    category: "First Complaint"
  },
  {
    date: "05/20/2025",
    provider: "VUMC Spine Center, Franklin (Dr. Byron Schneider, PM&R)",
    event: "First Orthopaedics/Spine specialist visit",
    detail: "Diagnosis: Suspected cervical radiculitis — C7 distribution. Symptoms: pain through trap, lateral shoulder, forearm into hand; superimposed numbness/tingling. Treatment plan: Physical therapy referral; Lyrica 75mg at night (for nerve pain); Diclofenac as needed after steroids complete.",
    category: "Specialist"
  },
  {
    date: "08/08/2025",
    provider: "VUMC Orthopaedics Franklin (Dr. Schneider) — Telemedicine",
    event: "Follow-up — Physical therapy plateau; persistent radiculopathy",
    detail: "PT initially helpful but symptoms returned. Pain in neck, trap, lateral shoulder, dorsal forearm, and wrist. Diagnosis: Cervical radiculopathy (persistent >8 weeks). Plan: Ordered cervical MRI (critical imaging). Re-referred to PT for manual therapy and dry needling. Considering EMG if MRI unrevealing.",
    category: "Specialist"
  },
  {
    date: "08/15/2025",
    provider: "VUMC Orthopaedics Franklin — Imaging",
    event: "MRI Cervical Spine #1 (without contrast)",
    detail: "IMPRESSION: Degenerative bone and disc disease. C6-C7: Prominent central disc bulging; bilateral facet arthropathy. Slight loss of disc space height at C5-6 and C6-7. No critical canal stenosis noted at this time. Radiologist: Dr. Daniel Starnes. Indication: Cervical radiculopathy.",
    category: "Imaging"
  },
  {
    date: "08/19/2025",
    provider: "VUMC Spine Center, Franklin (Dr. Schneider) — Telemedicine",
    event: "MRI review — C6-7 disc herniation confirmed; Cymbalta started",
    detail: "MRI reviewed: central disc protrusion at C6-7 abutting the cord with central canal stenosis; no cord signal change. Diagnosis: Neck and left arm pain emanating from C6-7 disc herniation. New medication: Cymbalta (duloxetine) — started today for nerve pain/radiculopathy. Discussed injection and surgical referral options.",
    category: "Specialist"
  },
  {
    date: "10/28/2025",
    provider: "VUMC Spine Center, Franklin (Dr. Schneider)",
    event: "Follow-up — PT failing; epidural injection scheduled",
    detail: "Symptoms unchanged. Left neck, trap, arm, forearm numbness into 4th and 5th digits. PT not effective this round. Unable to tolerate Lyrica. Positive Spurling's test on left (nerve compression sign). Diagnosis confirmed: Cervical radiculopathy, C6-7 disc herniation. Plan: Scheduled Left C6-7 Transforaminal Epidural Steroid Injection (TFESI). Prescribed Valium (procedural anxiolysis) and Cymbalta.",
    category: "Specialist"
  },
  {
    date: "10/28/2025",
    provider: "VUMC Orthopaedics Franklin — Imaging",
    event: "X-ray Ribs Right (2 views) — Cervical radiculopathy listed as indication",
    detail: "Ordered: Dr. Schneider. Resulted: Dr. Matthew Landon (11/15/2025). Indications: Rib pain AND Cervical radiculopathy (M54.12). Documents concurrent radiculopathy diagnosis alongside rib injury from a separate incident.",
    category: "Imaging"
  },
  {
    date: "12/01/2025",
    provider: "VUMC Health OnCall — Telemedicine",
    event: "Telemedicine visit — Noted upcoming steroid injection for neck",
    detail: "Clinical note references upcoming neck steroid injection (not yet scheduled at that point). Confirms ongoing neck condition management.",
    category: "Follow-up"
  },
  {
    date: "12/29/2025",
    provider: "VUMC Stallworth Rehab — Dr. Byron Schneider",
    event: "Left C6-7 Transforaminal Epidural Steroid Injection (TFESI)",
    detail: "PROCEDURE: Left C6-7 transforaminal epidural steroid injection with fluoroscopic guidance. Pre/Post Diagnosis: Cervical Disc Herniation with Radiculopathy. Medications: Dexamethasone 10mg/cc; 1% Lidocaine test dose; Omnipaque contrast. Needle: 25 gauge, 2.5\" Quincke. Post-procedure VAS: 0/10 (immediate relief).",
    category: "Procedure"
  },
  {
    date: "01/16/2026",
    provider: "VUMC Neurology (Recinos, PA-C) — Migraine follow-up",
    event: "Medical record documents herniated disk and nerve damage history",
    detail: "Visit primarily for migraines. Clinical note explicitly documents: \"history of head injuries, including a herniated disk in her neck\" and \"currently taking Cymbalta for nerve damage.\" Steroid injection noted to have provided only approximately 2 weeks of relief.",
    category: "Follow-up"
  },
  {
    date: "01/23/2026",
    provider: "VUMC Orthopaedics Franklin (Dr. Schneider) — Telemedicine",
    event: "Post-injection follow-up — Epidural failed; surgical candidacy discussed",
    detail: "Felt relief for only 2-3 days post-injection, then symptoms returned worse than baseline. Went to walk-in clinic for additional muscle relaxer, Toradol, and hydrocodone. Pain 5-7/10; radiating from neck through left arm into hand with numbness/tingling. Clinical assessment: C7 radicular pain pattern; epidural failed to provide sustained relief. Plan: Updated cervical MRI ordered; EMG/nerve conduction study ordered to assess radiculopathy. Resumed Cymbalta.",
    category: "Specialist"
  },
  {
    date: "02/15/2026",
    provider: "VUMC Imaging Services, Cool Springs",
    event: "MRI Cervical Spine #2 (without contrast) — Surgical-level findings",
    detail: "COMPARED TO: 8/15/2025. IMPRESSION: C6-C7 central disc extrusion with mild cranial extension; partial effacement of anterior thecal sac; mild cord indentation; mild canal stenosis. Radiologist: Dr. Amanda Nelson-Ragle. Indication: Cervical disc herniation (M50.20). Findings consistent with surgical intervention need.",
    category: "Imaging"
  },
  {
    date: "03/17/2026",
    provider: "Vanderbilt University Medical Center",
    event: "NECK SURGERY",
    detail: "Cervical spine surgery performed. Referenced throughout subsequent VUMC records as \"neck surgery on 03/17/2026\" and \"C spine surgery.\" Post-surgical pain medications include Norco (hydrocodone/acetaminophen). Post-op care continuing as of April/May 2026 follow-up visits.",
    category: "Surgery"
  },
  {
    date: "03/06/2026 onward",
    provider: "VUMC Post-Operative Care",
    event: "Post-surgical medications initiated",
    detail: "Multiple medications started in the post-surgical period (start dates 3/6/2026 and after): Norco (hydrocodone 10mg/acetaminophen 325mg) for post-op pain; Cymbalta continued for nerve damage. Medication list reviewed by VUMC provider on 4/27/2026.",
    category: "Post-Op"
  },
  {
    date: "04/27/2026",
    provider: "VUMC Primary Care, Brentwood",
    event: "Follow-up — Post-surgical recovery ongoing",
    detail: "Clinical note explicitly states: \"She has had a difficult several months with divorce, and assault, and C spine surgery. She's still having some radicular pain.\" Documents that patient has not been able to exercise regularly since neck problem began.",
    category: "Post-Op"
  }
];

const categoryColors = {
  "Baseline": "EAF4FB",
  "Incident": "FDECEA",
  "Worsening": "FDF6EC",
  "First Complaint": "E8F5E9",
  "Specialist": "EDE7F6",
  "Imaging": "E3F2FD",
  "Procedure": "FFF8E1",
  "Follow-up": "F5F5F5",
  "Surgery": "FCE4EC",
  "Post-Op": "F3E5F5"
};

const rows = [];

// Header row
rows.push(new TableRow({
  tableHeader: true,
  children: [
    headerCell("DATE", 1200),
    headerCell("PROVIDER / FACILITY", 2400),
    headerCell("EVENT / VISIT TYPE", 2200),
    headerCell("DETAILS & FINDINGS", 3560),
  ]
}));

// Data rows
timeline.forEach((item, i) => {
  const fill = categoryColors[item.category] || white;
  rows.push(new TableRow({
    children: [
      dataCell(item.date, 1200, fill, true),
      dataCell(item.provider, 2400, fill),
      dataCell(item.event, 2200, fill, true),
      dataCell(item.detail, 3560, fill),
    ]
  }));
});

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
  },
  numbering: { config: [] },
  sections: [{
    properties: {
      page: {
        size: { width: 15840, height: 12240 }, // Landscape: 11x8.5
        margin: { top: 864, right: 864, bottom: 864, left: 864 } // 0.6 inch margins
      }
    },
    children: [
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 60 },
        children: [
          new TextRun({ text: "MEDICAL TIMELINE: NECK INJURY FOLLOWING STRANGULATION", bold: true, size: 28, font: "Arial", color: headerBlue }),
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 60 },
        children: [
          new TextRun({ text: "Patient: Elizabeth A. Gifford  |  DOB: 02/25/1983  |  MRN: 046621275  |  Records Source: Vanderbilt University Medical Center (VUMC)", size: 19, font: "Arial", color: "444444" }),
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 120 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: headerBlue, space: 1 } },
        children: [
          new TextRun({ text: "Incident Date: October 13, 2024 — Strangulation by ex-husband  |  Surgery Date: March 17, 2026  |  Document prepared for legal proceedings", size: 19, font: "Arial", bold: true, color: "C0392B" }),
        ]
      }),
      new Paragraph({ spacing: { before: 80, after: 80 }, children: [new TextRun("")] }),
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [1200, 2400, 2200, 3560],
        rows
      }),
      new Paragraph({ spacing: { before: 120, after: 0 }, children: [new TextRun("")] }),
      new Paragraph({
        alignment: AlignmentType.LEFT,
        spacing: { before: 60, after: 0 },
        children: [
          new TextRun({ text: "NOTE: This timeline reflects records contained within Vanderbilt University Medical Center (VUMC) documentation only. Additional records from chiropractic care, walk-in clinics, EMG studies, and other providers referenced in the VUMC notes will be provided separately.", size: 17, font: "Arial", italic: true, color: "555555" })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.LEFT,
        spacing: { before: 40, after: 0 },
        children: [
          new TextRun({ text: "KEY: 10/08/2024 VUMC physical exam documented NORMAL cervical range of motion and no neck complaints — 5 days prior to the assault on 10/13/2024. This establishes pre-injury baseline.", size: 17, font: "Arial", bold: true, color: headerBlue })
        ]
      }),
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/home/claude/medical_timeline.docx', buffer);
  console.log('Done');
});

